// A host-owned MQTT connection. Credentials and live clients never enter component state.
({
  apiVersion:2,
  integrationApi:1,
  settings:{
    connectOnStart:{type:'boolean',default:false,label:'Connect on opening in Run / HTML'},
    showIndicators:{type:'boolean',default:true,label:'Show connection details'}
  },
  inputs:{url:{type:'string',default:'',label:'Broker WebSocket URL'},
    clientId:{type:'string',default:'',label:'Client ID (empty = unique per session)'}},
  mqttConfig(state){return {url:'url',clientId:'clientId',startup:state.connectOnStart===true};},
  outputs:{connected:{type:'boolean',role:'control'},status:{type:'string'},error:{type:'string'}},
  initState(){return {connectOnStart:false,showIndicators:true};},
  initStyle(){return {w:360,h:208,fontSize:16,fill:true,fillColor:'#ffffff',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1.5};},
  compute(inputs,state,context={}){
    const source=context.source||{};
    return {connected:source.connected===true,status:source.status||'disconnected',error:source.error||''};
  },
  _text(value,x,y,w,h,size,style,color=style.textColor||'#334155',weight=400){
    const content=String(value).replace(/\s+/g,' ');
    const chars=typeof Intl!=='undefined' && typeof Intl.Segmenter==='function'
      ?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(content),part=>part.segment):Array.from(content);
    let text='',used=0;
    for(let index=0;index<chars.length;index++){
      const char=chars[index],units=/[MWmw@#%]/.test(char)||char.codePointAt(0)>255?1.1:/[A-Z]/.test(char)?.88:.72;
      if((used+units+(index<chars.length-1?1.1:0))*size>w){text+='…';break;}
      text+=char;used+=units;
    }
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font:weight+' '+size+'px sans-serif',color,strokeOn:false};
  },
  children(state,style,w,h,editing,io={}){
    const scale=Math.min(w/360,h/208),pad=12*scale,out=io.outputs||{},name=io.name?.trim()||'MQTT Config';
    const text=(value,x,y,ww,hh,size,color,weight)=>this._text(value,x,y,ww,hh,size*scale,style,color,weight);
    const error=io.error||out.error||'',connected=out.connected===true,source=io.source||{};
    const labels={idle:'Disconnected',connected:'Connected',connecting:'Connecting…',reconnecting:'Reconnecting…',disconnected:'Disconnected',suspended:'Suspended',disabled:'Network disabled',error:'Connection error'};
    const status=labels[out.status]||out.status||'Disconnected';
    const children=[
      {type:'rect',x:0,y:0,w,h,fill:style.fill!==false,fillColor:style.fillColor||'#ffffff',strokeOn:style.strokeOn!==false,color:style.color||'#94a3b8',size:style.size,dash:style.dash},
      text(name,pad,pad,w-pad*2,21*scale,14,undefined,600),
      {type:'ellipse',x:pad,y:50*scale,w:10*scale,h:10*scale,fill:true,fillColor:error?'#dc2626':connected?'#15803d':['connecting','reconnecting'].includes(out.status)?'#d97706':'#94a3b8',strokeOn:false},
      text(status,pad+20*scale,42*scale,w-pad*2-20*scale,30*scale,21,error?'#b91c1c':undefined,600),
      text(error||source.connectedUrl||io.inputs?.url||'Set a broker URL in Edit',pad,80*scale,w-pad*2,20*scale,11,error?'#b91c1c':'#64748b')
    ];
    if(state.showIndicators!==false){
      children.push(text(io.inputs?.clientId?'Client ID: '+io.inputs.clientId:'Unique client ID for this session',pad,108*scale,w-pad*2,18*scale,10,'#64748b'),
        text(source.pending?'Draft changed · Apply / Connect to use it':state.connectOnStart?'Connects on opening in Run / HTML':'Manual connection',pad,128*scale,w-pad*2,18*scale,10,'#64748b'));
    }
    const y=h-54*scale,bh=36*scale,available=w-pad*4,widths=[available*.41,available*.29,available*.30];
    for(const [index,label] of ['Apply / Connect','Disconnect','Credentials'].entries()){
      const x=pad+widths.slice(0,index).reduce((sum,value)=>sum+value+pad,0),bw=widths[index];
      children.push({type:'rect',x,y,w:bw,h:bh,fill:true,fillColor:index===0?'#eef2ff':'#f8fafc',strokeOn:true,color:index===0?'#818cf8':'#cbd5e1',size:1},
        {type:'text',x:x+8*scale,y:y+9*scale,w:bw-16*scale,h:18*scale,text:label,plainText:true,align:'left',font:(index===0?'600 ':'400 ')+(index===2?9:10)*scale+'px sans-serif',color:index===0?'#3730a3':'#475569',strokeOn:false});
    }
    return children;
  },
  handles(state,w,h){
    const scale=Math.min(w/360,h/208),pad=12*scale,available=w-pad*4,widths=[available*.41,available*.29,available*.30],y=h-36*scale;
    return ['connect','disconnect','credentials'].map((id,index)=>({id,kind:'action',x:pad+widths.slice(0,index).reduce((sum,value)=>sum+value+pad,0)+widths[index]/2,y,
      action:{type:['mqttConnect','mqttDisconnect','mqttCredentials'][index]}}));
  },
  hitEdit(state,x,y,w,h){
    const scale=Math.min(w/360,h/208),pad=12*scale,available=w-pad*4,widths=[available*.41,available*.29,available*.30];
    if(y<h-54*scale || y>h-18*scale)return null;
    for(let index=0;index<3;index++){const left=pad+widths.slice(0,index).reduce((sum,value)=>sum+value+pad,0);if(x>=left && x<=left+widths[index])return ['connect','disconnect','credentials'][index];}
    return null;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,io);}
})

// A numeric source with configurable bounds and step. Click the value to type a number.
// The slider, buttons, and direct entry use the same step grid, anchored at the minimum.
({
  apiVersion:2,
  inputs:{min:{role:'control',type:'number',default:0},max:{role:'control',type:'number',default:100},step:{role:'control',type:'number',default:1}},
  outputs:{value:{type:'number'}},
  initState(){return {value:50};},
  initStyle(){return {w:240,h:130,fontSize:20,strokeOn:false};},
  _config(inputs={}){
    const {min=0,max=100,step=1}=inputs;
    if(!Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(step))throw new Error('Bounds and step must be finite numbers');
    if(min>max)throw new Error('Minimum must not exceed maximum');
    if(step<=0)throw new Error('Step must be greater than zero');
    if(!Number.isFinite(max-min) || !Number.isFinite((max-min)/step))throw new Error('Range or step is outside the numeric range');
    return {min,max,step};
  },
  _snap(value,config){
    const {min,max,step}=config;
    value=Number.isFinite(value)?Math.max(min,Math.min(max,value)):min;
    if(value===min || value===max)return value||0;
    const ticks=Math.round((value-min)/step),raw=Math.max(min,Math.min(max,min+ticks*step));
    const decimals=value=>{const [mantissa,exponent='0']=String(value).split('e');return Math.max(0,(mantissa.split('.')[1]||'').length-Number(exponent));};
    const precision=Math.max(decimals(min),decimals(step));
    const snapped=precision<=100?Number(raw.toFixed(precision)):raw;
    return Math.max(min,Math.min(max,snapped))||0;
  },
  compute(inputs,state){const config=this._config(inputs);return {value:this._snap(state.value,config)};},
  _number(value){return !Number.isFinite(value)?'—':Number.isSafeInteger(value)?String(value):String(Number(value.toPrecision(8)));},
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  children(state,style,w,h,editing,io={}){
    let config;try{config=this._config(io.inputs);}catch{}
    const value=io.outputs?.value,available=!io.error && Number.isFinite(value) && !!config;
    const scale=Math.min(w/240,h/130),pad=Math.min(20*scale,w*.15),y=h*.55;
    const textColor=style.textColor||style.color,font=size=>'600 '+Math.max(6,size*scale)+'px sans-serif';
    const position=available && config.max!==config.min?(value-config.min)/(config.max-config.min):.5;
    const label=this._number(value);
    const children=[
      {type:'rect',x:0,y:0,w,h,fill:style.fill,fillColor:style.fillColor,strokeOn:style.strokeOn,color:style.color,size:style.size},
      {type:'text',x:0,y:0,w,h:h*.22,...this._caption(io.name,'Number control',w,h*.22,style),align:'center',color:textColor,strokeOn:false,fill:false},
      {type:'text',x:w*.12,y:h*.23,w:w*.76,h:h*.23,text:available?label:'—',align:'center',font:font(20),color:textColor,strokeOn:false,fill:false},
      {type:'line',x1:pad,y1:y,x2:w-pad,y2:y,color:style.color,size:2}
    ];
    if(available){
      children.push({type:'ellipse',x:pad+(w-pad*2)*position-6*scale,y:y-6*scale,w:12*scale,h:12*scale,fill:true,fillColor:style.color,strokeOn:false});
      if(editing){
        for(const [x,label] of [[0,'− '+this._number(config.step)],[w/2,'+ '+this._number(config.step)]]){
          children.push({type:'rect',x:x+4*scale,y:h*.72,w:Math.max(0,w/2-8*scale),h:h*.25,strokeOn:true,color:style.color,size:1,fill:false});
          children.push({type:'text',x,y:h*.72,w:w/2,h:h*.25,text:label,align:'center',font:font(16),color:textColor,strokeOn:false,fill:false});
        }
      }
    }else{
      children.push({type:'text',x:0,y:h*.72,w,h:h*.25,text:'Check bounds and step in Edit',align:'center',font:font(10),color:'#92400e',strokeOn:false,fill:false});
    }
    return children;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,false,{...io,outputs:{}});},
  handles(state,w,h,style,io={}){
    let config;try{config=this._config(io.inputs);}catch{return [];}
    const value=io.outputs?.value;if(!Number.isFinite(value) || io.error)return [];
    const scale=Math.min(w/240,h/130),pad=Math.min(20*scale,w*.15);
    const position=config.max===config.min?.5:(value-config.min)/(config.max-config.min);
    return [
      {id:'value',x:pad+(w-pad*2)*position,y:h*.55},
      {id:'entry',x:w/2,y:h*.345,kind:'number',value,min:config.min,max:config.max,step:config.step},
      {id:'minus',x:w/4,y:h*.84,kind:'click'},
      {id:'plus',x:w*.75,y:h*.84,kind:'click'}
    ];
  },
  hitEdit(state,lx,ly,w,h){
    if(lx<0 || lx>w)return null;
    if(ly>=h*.72 && ly<=h)return lx<w/2?'minus':'plus';
    if(ly>=h*.23 && ly<=h*.46)return 'entry';
    if(Math.abs(ly-h*.55)<=Math.min(18,h*.09))return 'value';
    return null;
  },
  dragEdit(state,handle,lx,ly,w,h,style,io={}){
    const config=this._config(io.inputs),current=this._snap(io.outputs?.value??state.value,config);
    const scale=Math.min(w/240,h/130),pad=Math.min(20*scale,w*.15);
    let value=current;
    if(handle==='value')value=config.min+Math.max(0,Math.min(1,(lx-pad)/Math.max(1,w-pad*2)))*(config.max-config.min);
    else if(handle==='entry'){if(!Number.isFinite(lx))throw new Error('Enter a finite number');value=lx;}
    else if(handle==='plus')value=config.max-current<=config.step?config.max:current+config.step;
    else if(handle==='minus')value=current-config.min<=config.step?config.min:current-config.step;
    if(!Number.isFinite(value))throw new Error('Calculation overflow');
    return {state:{...state,value:this._snap(value,config)}};
  }
})

// Wall-clock readings and nominal 100 ms boundary pulses in a selected timezone.
// Reopening, changing timezone, and missed/adjusted clock time re-prime without replaying ticks.
// The host schedules transitions; compute and image exports use the last settled snapshot.
({
  apiVersion:2,
  wakePolicy:'latest',
  inputs:{timezone:{role:'control',type:'string',default:'local'}},
  outputs:{second:{role:'control',type:'boolean'},minute:{role:'control',type:'boolean'},hour:{role:'control',type:'boolean'},halfDay:{role:'control',type:'boolean'},time:{type:'string'}},
  initState(){return {time:'00:00:00',second:false,minute:false,hour:false,halfDay:false,showIndicators:true};},
  initStyle(){return {w:220,h:300,strokeOn:false,fontSize:16};},
  _formatter(timezone){
    if(typeof timezone!=='string' || !timezone.trim() || timezone.length>128)throw new Error('Timezone must be local or a valid timezone name, such as Europe/Berlin');
    const zone=timezone.trim();
    try{return new Intl.DateTimeFormat('en-GB',{...(zone.toLowerCase()==='local'?{}:{timeZone:zone}),
      hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',numberingSystem:'latn'});}
    catch(_){throw new Error('Invalid timezone: use local, UTC, or a timezone name such as Europe/Berlin');}
  },
  _validate(state){
    if(typeof state.time!=='string' || !/^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(state.time) ||
       ['second','minute','hour','halfDay'].some(key=>typeof state[key]!=='boolean') || typeof state.showIndicators!=='boolean')throw new Error('Invalid Live clock state');
  },
  transition(inputs,state,memory,context){
    const {now}=context;
    this._validate(state);
    if(!Number.isFinite(now) || now<0)throw new Error('Live clock requires a valid monotonic time');
    const formatter=this._formatter(inputs.timezone),wall=Date.now();
    if(!Number.isFinite(wall) || Math.abs(wall)>8640000000000000)throw new Error('Live clock requires a valid wall-clock time');
    const parts=Object.fromEntries(formatter.formatToParts(new Date(wall)).map(part=>[part.type,part.value]));
    const hour=Number(parts.hour)%24,minute=Number(parts.minute),second=Number(parts.second);
    const time=[hour,minute,second].map(value=>String(value).padStart(2,'0')).join(':');
    const zone=formatter.resolvedOptions().timeZone,epochSecond=Math.floor(wall/1000);
    const fresh=memory==null || (typeof memory==='object' && !Array.isArray(memory) && Object.keys(memory).length===0);
    if(!fresh && (typeof memory.zone!=='string' || !Number.isFinite(memory.wall) || !Number.isSafeInteger(memory.epochSecond) ||
       memory.epochSecond!==Math.floor(memory.wall/1000) || !Number.isFinite(memory.now) || memory.now<0 ||
       (memory.until!==null && (!Number.isFinite(memory.until) || memory.until<=memory.now))))throw new Error('Invalid Live clock scheduling memory');
    // Replaying an earlier queued signal must not consume this wall-clock wake.
    if(context.historical && !fresh && memory.zone===zone){
      const nextWakeAt=memory.until===null?memory.now+1000-((memory.wall%1000+1000)%1000):memory.until;
      return {state,memory,nextWakeAt};
    }
    // Active-document time pauses while hidden. A wall/active-time discontinuity resets observation,
    // as does a backwards clock adjustment. Small scheduling jitter does not erase a normal tick.
    const restart=fresh || memory.zone!==zone || wall<memory.wall || now<memory.now ||
      Math.abs((wall-memory.wall)-(now-memory.now))>500;
    let secondTick=false,minuteTick=false,hourTick=false,halfDayTick=false,until=null;
    if(!restart){
      if(memory.until!==null){
        // An overdue high must fall before another rise; never turn missed ticks into a burst.
        if(now<memory.until){
          secondTick=state.second;minuteTick=state.minute;hourTick=state.hour;halfDayTick=state.halfDay;until=memory.until;
        }
      }else if(epochSecond===memory.epochSecond+1){
        secondTick=true;minuteTick=second===0;hourTick=minuteTick && minute===0;halfDayTick=hourTick && hour%12===0;
        until=now+100;
      }
    }
    const nextWakeAt=until===null?now+1000-((wall%1000+1000)%1000):until;
    if(!Number.isFinite(nextWakeAt) || nextWakeAt<=now)throw new Error('Live clock wake time is outside the numeric range');
    return {state:{...state,time,second:secondTick,minute:minuteTick,hour:hourTick,halfDay:halfDayTick},
      memory:{zone,wall,now,epochSecond,until},nextWakeAt};
  },
  publish(state){
    this._validate(state);
    return {second:state.second,minute:state.minute,hour:state.hour,halfDay:state.halfDay,time:state.time};
  },
  compute(inputs,state){
    this._formatter(inputs.timezone);this._validate(state);
    return {second:state.second,minute:state.minute,hour:state.hour,halfDay:state.halfDay,time:state.time};
  },
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  children(state,style,w,h,editing,io={}){
    const available=!io.error && /^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(io.outputs?.time);
    const scale=Math.min(w/220,h/300),top=24*scale,d=Math.max(1,Math.min(w-16*scale,h-112*scale));
    const cx=w/2,cy=top+d/2,r=d/2,thin=Math.max(1,(style.size||2)/2);
    const text=(value,x,y,width,height,size)=>({type:'text',x,y,w:width,h:height,text:value,align:'center',
      font:'600 '+Math.max(6,size*scale)+'px sans-serif',color:style.textColor||style.color,textColor:style.textColor||style.color,strokeOn:false,fill:false});
    const items=[{...text('',0,0,w,22*scale,16),...this._caption(io.name,'Live clock',w,22*scale,{...style,fontSize:16*scale})},
      {type:'ellipse',x:cx-r,y:top,w:d,h:d,color:style.color,size:thin,strokeOn:true,fill:style.fill,fillColor:style.fillColor}];
    for(let i=0;i<12;i++){
      const angle=i/12*Math.PI*2;
      items.push({type:'line',x1:cx+Math.sin(angle)*r*.84,y1:cy-Math.cos(angle)*r*.84,
        x2:cx+Math.sin(angle)*r*.95,y2:cy-Math.cos(angle)*r*.95,color:style.color,size:thin});
    }
    if(available){
      const [hour,minute,second]=io.outputs.time.split(':').map(Number),minutes=minute+second/60,hours=hour%12+minutes/60;
      for(const [value,total,length,size,color] of [[hours,12,.5,style.size||2,style.color],
        [minutes,60,.72,style.size||2,style.color],[second,60,.82,thin,style.textColor||style.color]]){
        const angle=value/total*Math.PI*2;
        items.push({type:'line',x1:cx,y1:cy,x2:cx+Math.sin(angle)*r*length,y2:cy-Math.cos(angle)*r*length,color,size});
      }
    }
    const timezone=typeof io.inputs?.timezone==='string'?io.inputs.timezone.trim():'local';
    const zoneLabel=available?(timezone.toLowerCase()==='local'?'Local time':timezone):/timezone/i.test(io.error||'')?'Invalid timezone':'Clock unavailable';
    items.push(text(available?io.outputs.time:'--:--:--',0,top+d+6*scale,w,22*scale,20),
      {...text('',0,top+d+31*scale,w,16*scale,11),...this._caption(zoneLabel,'Local time',w,16*scale,{...style,fontSize:11*scale}),
        ...(!available?{color:'#92400e',textColor:'#92400e'}:{})});
    if(state.showIndicators!==false){
      for(const [index,[key,label]] of [['second','1 s'],['minute','1 m'],['hour','1 h'],['halfDay','12 h']].entries()){
        const x=w*(index+.5)/4,y=h-28*scale,radius=3*scale;
        items.push({type:'ellipse',x:x-17*scale-radius,y:y-radius,w:radius*2,h:radius*2,fill:true,
          fillColor:available?(io.outputs[key]?'#15803d':'#94a3b8'):'#fbbf24',strokeOn:false},
          text(label,x-11*scale,y-8*scale,35*scale,16*scale,9));
      }
    }
    if(editing && available){
      items.push({type:'rect',x:0,y:h-17*scale,w,h:17*scale,fill:true,fillColor:'#e2e8f0',strokeOn:false,editorOnly:true},
        {...text('Indicators: '+(state.showIndicators?'on':'off'),0,h-17*scale,w,17*scale,10),editorOnly:true});
    }
    return items;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,false,{...io,outputs:{}});},
  handles(state,w,h){return [{id:'indicators',x:w/2,y:h-8.5*Math.min(w/220,h/300),kind:'click',editorOnly:true}];},
  hitEdit(state,x,y,w,h){return x>=0 && x<=w && y>=h-17*Math.min(w/220,h/300) && y<=h?'indicators':null;},
  dragEdit(state,handle){return {state:handle==='indicators'?{...state,showIndicators:!state.showIndicators}:state};}
})

// One Workspace settings component supplies presentation defaults and startup configuration.
// Execution mode and initial sketch are authoring settings, never live control inputs.
({
  apiVersion:2,
  settings:{executionMode:{type:'string',default:'active sketch',options:['active sketch','whole workspace'],label:'Execution mode'}},
  workspaceSettings:{title:'title',showTabs:'showTabs',showWiring:'showWiring',showSimulationControls:'showSimulationControls'},
  initState(){return {executionMode:'active sketch',initialSketchId:'',tabVisibility:[]};},
